~~~go
func pairSum(sorted []int, target int) (int, int, bool) {
    left, right := 0, len(sorted)-1
    for left < right {
        sum := sorted[left] + sorted[right]
        if sum == target { return left, right, true }
        if sum < target { left++ } else { right-- }
    }
    return 0, 0, false
}
~~~

